# -*- coding: utf-8 -*-
"""测试用发票样张：合成一张贴近真实版式的增值税专用发票（文本 + 行框坐标）。

为什么用合成样张而不是真票图片：
  ① 真票含企业名称/税号，不能进仓库；
  ② 抽取逻辑的输入是"文本 + 坐标"，不是像素——合成同样的坐标就能覆盖同样的分支，
     且失败时能一眼看出是哪个框的问题。

版式要点（与真实专票一致的地方）：
  - 标题带省份前缀（"北京增值税专用发票"）；
  - 右上票头四要素（代码 10 位 / 号码 8 位 / 开票日期 / 机器编号）；
  - 购方、销方各四要素（名称 / 税号 / 地址电话 / 开户行账号）；
  - 8 列明细表头 + 一行明细（**单位列为空**，这是真实票样里的常见情形，
    也是列对齐逻辑最容易出错的场景）；
  - 合计行与价税合计（大写/小写）；
  - 票尾签章（收款人/复核/开票人）。
"""
from __future__ import annotations

from typing import Any, Dict, List, Tuple

W, H = 1000, 1400


def _ln(text: str, x0: float, y0: float, x1: float, y1: float) -> Dict[str, Any]:
    return {"text": text, "x0": x0, "y0": y0, "x1": x1, "y1": y1}


def lines() -> List[Dict[str, Any]]:
    return [
        _ln("北京增值税专用发票", 300, 30, 700, 70),
        _ln("发票代码", 700, 120, 770, 140), _ln("1100153130", 775, 120, 870, 140),
        _ln("发票号码", 700, 150, 770, 170), _ln("12345678", 775, 150, 870, 170),
        _ln("开票日期", 700, 180, 770, 200), _ln("2023年05月18日", 775, 180, 900, 200),
        _ln("机器编号", 700, 210, 770, 230), _ln("661512345678", 775, 210, 900, 230),
        _ln("密码区", 880, 260, 900, 340),
        _ln("购买方", 60, 380, 130, 400),
        _ln("名 称：北京星辰科技有限公司", 150, 380, 500, 400),
        _ln("纳税人识别号：91110108MA01ABCDEF", 150, 410, 520, 430),
        _ln("地址、电话：北京市海淀区中关村大街1号 010-12345678", 150, 440, 620, 460),
        _ln("开户行及账号：中国银行北京分行 1234567890", 150, 470, 620, 490),
        _ln("货物或应税劳务、服务名称", 60, 560, 300, 580),
        _ln("规格型号", 310, 560, 380, 580),
        _ln("单位", 390, 560, 430, 580),
        _ln("数量", 440, 560, 480, 580),
        _ln("单价", 490, 560, 540, 580),
        _ln("金额", 550, 560, 600, 580),
        _ln("税率", 610, 560, 650, 580),
        _ln("税额", 660, 560, 710, 580),
        _ln("*信息技术服务*技术服务费", 60, 600, 300, 620),
        _ln("XH-01", 310, 600, 380, 620),
        _ln("1", 440, 600, 480, 620),
        _ln("10000.00", 490, 600, 540, 620),
        _ln("10000.00", 550, 600, 600, 620),
        _ln("6%", 610, 600, 650, 620),
        _ln("600.00", 660, 600, 710, 620),
        _ln("合 计", 60, 680, 150, 700),
        _ln("¥10000.00", 540, 680, 600, 700),
        _ln("¥600.00", 650, 680, 710, 700),
        _ln("价税合计（大写）", 60, 720, 220, 740),
        _ln("⊙壹万零陆佰元整", 230, 720, 400, 740),
        _ln("（小写）¥10600.00", 620, 720, 760, 740),
        _ln("销售方", 60, 800, 130, 820),
        _ln("名 称：上海云图信息有限公司", 150, 800, 500, 820),
        _ln("纳税人识别号：91310115MA1K2BCD3E", 150, 830, 520, 850),
        _ln("地址、电话：上海市浦东新区张江路5号 021-87654321", 150, 860, 620, 880),
        _ln("开户行及账号：工商银行上海分行 9876543210", 150, 890, 620, 910),
        _ln("收款人：张三", 60, 1300, 200, 1320),
        _ln("复核：李四", 260, 1300, 380, 1320),
        _ln("开票人：王五", 440, 1300, 560, 1320),
        _ln("销售方：（章）", 700, 1300, 850, 1320),
    ]


def text() -> str:
    return "\n".join(l["text"] for l in lines())


def page() -> Dict[str, Any]:
    """可直接喂给 apply_schemas / render_schema 的 page 字典。"""
    return {"page": 1, "text": text(), "raw_text": text(),
            "lines": lines(), "img_w": W, "img_h": H}


def sample() -> Tuple[str, List[Dict[str, Any]], int, int]:
    return text(), lines(), W, H
